/**
 * Datos de rutas de transporte público, agrupados por empresa (operador).
 *
 * Convertido desde `route_store.dart` (app móvil). Los campos de negocio que
 * no existen en el origen (tarifa, terminal, horarios) quedan en `null` a
 * propósito -- falta capturarlos, no se inventaron valores.
 */

export type LatLngLiteral = {
  lat: number;
  lng: number;
};

export type RouteStop = {
  /** Número de parada o "Inicio/Fin"; `null` si el dato de origen no traía etiqueta. */
  label: string | null;
  isTerminal: boolean;
  lat: number;
  lng: number;
};

export type TransitRouteColor = "violeta" | "amarillo" | "rojo" | "azul";

/** Tomado directamente del color dominante de cada ícono de parada. */
export const ROUTE_COLOR_HEX: Record<TransitRouteColor, string> = {
  violeta: "#5A00A7",
  amarillo: "#A09B3F",
  rojo: "#80001F",
  azul: "#2A67BE",
};

/** Color de texto con buen contraste sobre cada `ROUTE_COLOR_HEX`. */
export const ROUTE_COLOR_TEXT: Record<TransitRouteColor, string> = {
  violeta: "#FFFFFF",
  amarillo: "#FFFFFF",
  rojo: "#FFFFFF",
  azul: "#FFFFFF",
};

/** Ícono de parada por empresa (mismo que la app de Android). */
export const ROUTE_STOP_ICON: Record<TransitRouteColor, string> = {
  violeta: "/violeta_bus_stop.png",
  amarillo: "/amarillos_bus_stop.png",
  rojo: "/rojos_bus_stop.png",
  azul: "/vigia_bus_stop.png",
};

export type TransitRoute = {
  id: string;
  slug: string;
  name: string;
  icon: string;
  color: TransitRouteColor;
  city: string;
  operatorSlug: string;
  /** TODO: no está en el dato de origen, definir tarifa real. */
  fare: number | null;
  stops: RouteStop[];
  path: LatLngLiteral[];
};

export type TransitOperator = {
  slug: string;
  name: string;
  city: string;
  /** TODO: no está en el dato de origen. */
  terminalLocation: string | null;
  /** TODO: no está en el dato de origen. */
  firstDeparture: string | null;
  /** TODO: no está en el dato de origen. */
  lastDeparture: string | null;
};

